#!/usr/bin/env node
// Write apps/ios/Version.xcconfig from /version.json.
//
// The Xcode project stores no version of its own: debug.xcconfig and
// release.xcconfig include this generated file, which is the only place
// MARKETING_VERSION and CURRENT_PROJECT_VERSION are set. It is gitignored —
// regenerated by `apps/web` postinstall, by every native build
// (apps/web/scripts/build-and-sync.sh), and by the fastlane iOS lane before it
// archives, so a release can never pick up a stale number. build-and-sync.sh
// also fails the build if the version Xcode resolved does not match
// version.json, since a missing #include is silently ignored.
//
// Set TASFER_BUILD_NUMBER to override the derived build number — needed only to
// re-upload a build of a version TestFlight has already seen.
import { existsSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { appVersion, buildNumber, repoRoot } from "./app-version.mjs";

const version = appVersion();

let build = buildNumber(version);
const override = process.env.TASFER_BUILD_NUMBER;
if (override) {
  if (!/^\d+$/.test(override)) {
    console.error(`gen-ios-version: TASFER_BUILD_NUMBER must be a positive integer, got "${override}"`);
    process.exit(1);
  }
  build = Number(override);
}

// This runs from `apps/web` postinstall, which also happens on hosts that only
// build the web app. Nothing to write there, and the Xcode build fails loudly on
// the missing include anyway, so a missing project is not an error.
const iosDir = resolve(repoRoot, "apps/ios");
if (!existsSync(iosDir)) {
  console.log("gen-ios-version: no apps/ios directory, skipping");
  process.exit(0);
}

const path = resolve(iosDir, "Version.xcconfig");
writeFileSync(
  path,
  `// Generated by scripts/release/gen-ios-version.mjs from /version.json.
// Do not edit — edit version.json instead. This file is gitignored.
MARKETING_VERSION = ${version}
CURRENT_PROJECT_VERSION = ${build}
`,
);

console.log(`gen-ios-version: iOS -> ${version} (build ${build})`);
